  describe('prescriptions', () => {
    function inProgress(): Encounter {
      const encounter = arrived();
      encounter.start(new Date('2026-03-02T10:00:00Z'));
      return encounter;
    }

    it('records prescriptions while the encounter is in progress', () => {
      const encounter = inProgress();

      encounter.prescribe({ medicationCode: ' AMOX500 ', quantity: 3 });
      encounter.prescribe({ medicationCode: 'IBU400', quantity: 1 });

      expect(encounter.toSnapshot().prescriptions).toEqual([
        { medicationCode: 'AMOX500', quantity: 3 },
        { medicationCode: 'IBU400', quantity: 1 },
      ]);
    });

    it('keeps prescriptions after completion', () => {
      const encounter = inProgress();
      encounter.prescribe({ medicationCode: 'AMOX500', quantity: 3 });

      encounter.complete(record, new Date());

      expect(encounter.toSnapshot().prescriptions).toEqual([{ medicationCode: 'AMOX500', quantity: 3 }]);
    });

    it('cannot prescribe before the encounter starts or after it completes', () => {
      expect(() => arrived().prescribe({ medicationCode: 'AMOX500', quantity: 1 })).toThrow(
        InvalidEncounterTransitionError,
      );

      const encounter = inProgress();
      encounter.complete(record, new Date());
      expect(() => encounter.prescribe({ medicationCode: 'AMOX500', quantity: 1 })).toThrow(
        InvalidEncounterTransitionError,
      );
    });

    it.each([0, -1, 1.5, Number.NaN, undefined])('rejects quantity %s', (quantity) => {
      expect(() => inProgress().prescribe({ medicationCode: 'AMOX500', quantity: quantity as number })).toThrow(
        InvalidPrescriptionError,
      );
    });

    it('rejects a blank or missing medication code', () => {
      expect(() => inProgress().prescribe({ medicationCode: '  ', quantity: 1 })).toThrow(InvalidPrescriptionError);
      expect(() => inProgress().prescribe({ medicationCode: undefined as unknown as string, quantity: 1 })).toThrow(
        InvalidPrescriptionError,
      );
    });
  });
});
